// innerWidth - tylko widoczny obszar strony (viewport)
// outerWidth - cale okno przegladarki, wraz z paskami narzedzi i ramkami
console.log(window.innerWidth, window.outerWidth);

window.addEventListener("load", () => {
  console.log("Wszystko zaladowane");
});
// load wywoluje sie PoZNIEJ niz DOMContentLoaded - czeka az wszystkie
// obrazy, arkusze CSS i zewnetrzne skrypty beda w pelni pobrane.

window.addEventListener("beforeunload", (e) => {
  e.returnValue = "";
});
// Naduzywanie beforeunload (np. na kazdej stronie, bez faktycznych
// niezapisanych zmian) irytuje uzytkownikow i przegladarki coraz
// bardziej ograniczaja mozliwosc wyswietlania wlasnego tekstu w tym
// dialogu - uzywaj tylko wtedy, gdy uzytkownik faktycznie moglby
// stracic niezapisana prace.
